CREATE TABLE IF NOT EXISTS usuarios(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS roles(id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,nombre VARCHAR(80) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS usuario_rol(usuario_id BIGINT UNSIGNED NOT NULL,rol_id SMALLINT UNSIGNED NOT NULL,PRIMARY KEY(usuario_id,rol_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(rol_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sesiones(token_hash CHAR(64) PRIMARY KEY,usuario_id BIGINT UNSIGNED NOT NULL,expira_en DATETIME NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,INDEX idx_sesion_expira(expira_en)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS areas(id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(90) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categorias(id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(90) NOT NULL UNIQUE,activo BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS materiales(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(48) NOT NULL UNIQUE,nombre VARCHAR(160) NOT NULL,descripcion TEXT NULL,especificacion VARCHAR(255) NOT NULL DEFAULT '',unidad VARCHAR(24) NOT NULL,categoria_id SMALLINT UNSIGNED NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(categoria_id) REFERENCES categorias(id),INDEX idx_material_nombre(nombre)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS material_alias(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,material_id BIGINT UNSIGNED NOT NULL,alias VARCHAR(160) NOT NULL,origen VARCHAR(80) NULL,UNIQUE KEY uq_alias_material(alias,material_id),FOREIGN KEY(material_id) REFERENCES materiales(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS proveedores(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(32) NOT NULL UNIQUE,nombre VARCHAR(150) NOT NULL,contacto VARCHAR(120) NULL,email VARCHAR(190) NULL,telefono VARCHAR(40) NULL,condiciones_pago VARCHAR(160) NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS proveedor_material(material_id BIGINT UNSIGNED NOT NULL,proveedor_id BIGINT UNSIGNED NOT NULL,sku_externo VARCHAR(80) NULL,plazo_dias SMALLINT UNSIGNED NOT NULL DEFAULT 0,activo BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(material_id,proveedor_id),FOREIGN KEY(material_id) REFERENCES materiales(id),FOREIGN KEY(proveedor_id) REFERENCES proveedores(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS precios_proveedor(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,material_id BIGINT UNSIGNED NOT NULL,proveedor_id BIGINT UNSIGNED NOT NULL,precio_crc DECIMAL(14,2) NOT NULL CHECK(precio_crc>=0),vigente_desde DATE NOT NULL,vigente_hasta DATE NULL,fuente VARCHAR(160) NULL,FOREIGN KEY(material_id,proveedor_id) REFERENCES proveedor_material(material_id,proveedor_id),INDEX idx_precio_actual(material_id,proveedor_id,vigente_desde)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ubicaciones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(40) NOT NULL UNIQUE,nombre VARCHAR(120) NOT NULL,tipo ENUM('BODEGA','OBRA') NOT NULL,area_id SMALLINT UNSIGNED NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(area_id) REFERENCES areas(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stock_locks(material_id BIGINT UNSIGNED NOT NULL,ubicacion_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(material_id,ubicacion_id),FOREIGN KEY(material_id) REFERENCES materiales(id),FOREIGN KEY(ubicacion_id) REFERENCES ubicaciones(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS politicas_stock(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,material_id BIGINT UNSIGNED NOT NULL,ubicacion_id BIGINT UNSIGNED NOT NULL,stock_min DECIMAL(14,3) NOT NULL DEFAULT 0,stock_max DECIMAL(14,3) NULL,demanda_prom DECIMAL(14,3) NOT NULL,demanda_max DECIMAL(14,3) NOT NULL,lead_time_dias DECIMAL(8,2) NOT NULL,UNIQUE KEY uq_politica(material_id,ubicacion_id),CHECK(demanda_max>=demanda_prom),CHECK(lead_time_dias>=0),FOREIGN KEY(material_id) REFERENCES materiales(id),FOREIGN KEY(ubicacion_id) REFERENCES ubicaciones(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contratos(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(48) NOT NULL UNIQUE,proveedor_id BIGINT UNSIGNED NOT NULL,fecha_inicio DATE NOT NULL,fecha_fin DATE NULL,condiciones VARCHAR(255) NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(proveedor_id) REFERENCES proveedores(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contrato_detalle(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,contrato_id BIGINT UNSIGNED NOT NULL,material_id BIGINT UNSIGNED NOT NULL,precio_crc DECIMAL(14,2) NOT NULL,CHECK(precio_crc>=0),UNIQUE KEY uq_contrato_material(contrato_id,material_id),FOREIGN KEY(contrato_id) REFERENCES contratos(id),FOREIGN KEY(material_id) REFERENCES materiales(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS requisiciones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(48) NOT NULL UNIQUE,area_id SMALLINT UNSIGNED NOT NULL,solicitante_id BIGINT UNSIGNED NOT NULL,estado ENUM('BORRADOR','PENDIENTE','APROBADA','RECHAZADA','CERRADA') NOT NULL DEFAULT 'BORRADOR',motivo VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(area_id) REFERENCES areas(id),FOREIGN KEY(solicitante_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS requisicion_detalle(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,requisicion_id BIGINT UNSIGNED NOT NULL,material_id BIGINT UNSIGNED NOT NULL,cantidad DECIMAL(14,3) NOT NULL CHECK(cantidad>0),FOREIGN KEY(requisicion_id) REFERENCES requisiciones(id),FOREIGN KEY(material_id) REFERENCES materiales(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ordenes_compra(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(48) NOT NULL UNIQUE,proveedor_id BIGINT UNSIGNED NOT NULL,area_id SMALLINT UNSIGNED NOT NULL,fecha DATE NOT NULL,estado ENUM('BORRADOR','PENDIENTE','APROBADA','RECHAZADA','PARCIAL','RECIBIDA','CERRADA') NOT NULL DEFAULT 'PENDIENTE',comprador_id BIGINT UNSIGNED NULL,moneda CHAR(3) NOT NULL DEFAULT 'CRC',notas VARCHAR(500) NULL,requisicion_id BIGINT UNSIGNED NULL,FOREIGN KEY(requisicion_id) REFERENCES requisiciones(id),FOREIGN KEY(proveedor_id) REFERENCES proveedores(id),FOREIGN KEY(area_id) REFERENCES areas(id),FOREIGN KEY(comprador_id) REFERENCES usuarios(id),INDEX idx_oc_prov_fecha(proveedor_id,fecha),INDEX idx_oc_numero(numero)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orden_compra_detalle(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,orden_id BIGINT UNSIGNED NOT NULL,material_id BIGINT UNSIGNED NOT NULL,cantidad DECIMAL(14,3) NOT NULL CHECK(cantidad>0),precio_unitario_historico DECIMAL(14,2) NOT NULL CHECK(precio_unitario_historico>=0),UNIQUE KEY uq_oc_material(orden_id,material_id),FOREIGN KEY(orden_id) REFERENCES ordenes_compra(id),FOREIGN KEY(material_id) REFERENCES materiales(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS aprobaciones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,orden_id BIGINT UNSIGNED NOT NULL,usuario_id BIGINT UNSIGNED NOT NULL,decision ENUM('APROBADA','RECHAZADA') NOT NULL,comentario VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(orden_id) REFERENCES ordenes_compra(id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS recepciones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(48) NOT NULL UNIQUE,orden_id BIGINT UNSIGNED NOT NULL,ubicacion_id BIGINT UNSIGNED NOT NULL,documento VARCHAR(160) NOT NULL,recibido_por BIGINT UNSIGNED NULL,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(orden_id) REFERENCES ordenes_compra(id),FOREIGN KEY(ubicacion_id) REFERENCES ubicaciones(id),FOREIGN KEY(recibido_por) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS recepcion_detalle(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,recepcion_id BIGINT UNSIGNED NOT NULL,orden_detalle_id BIGINT UNSIGNED NOT NULL,cantidad DECIMAL(14,3) NOT NULL CHECK(cantidad>0),UNIQUE KEY uq_receipt_po_line(recepcion_id,orden_detalle_id),FOREIGN KEY(recepcion_id) REFERENCES recepciones(id),FOREIGN KEY(orden_detalle_id) REFERENCES orden_compra_detalle(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS movimientos_stock(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,material_id BIGINT UNSIGNED NOT NULL,cantidad DECIMAL(14,3) NOT NULL CHECK(cantidad>0),tipo ENUM('APERTURA','ENTRADA','SALIDA','TRASLADO','AJUSTE_POSITIVO','AJUSTE_NEGATIVO','REVERSA') NOT NULL,ubicacion_origen_id BIGINT UNSIGNED NULL,ubicacion_destino_id BIGINT UNSIGNED NULL,usuario_id BIGINT UNSIGNED NULL,documento VARCHAR(160) NULL,motivo VARCHAR(500) NULL,correlacion CHAR(36) NULL,idempotency_key VARCHAR(100) NULL UNIQUE,recepcion_detalle_id BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(material_id) REFERENCES materiales(id),FOREIGN KEY(ubicacion_origen_id) REFERENCES ubicaciones(id),FOREIGN KEY(ubicacion_destino_id) REFERENCES ubicaciones(id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(recepcion_detalle_id) REFERENCES recepcion_detalle(id),INDEX idx_mov_material_fecha(material_id,created_at),INDEX idx_mov_destino(ubicacion_destino_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS alertas(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,material_id BIGINT UNSIGNED NOT NULL,ubicacion_id BIGINT UNSIGNED NOT NULL,tipo ENUM('REORDEN','SISTEMA') NOT NULL DEFAULT 'REORDEN',estado ENUM('ABIERTA','ATENDIDA','RESUELTA') NOT NULL DEFAULT 'ABIERTA',stock_actual DECIMAL(14,3) NOT NULL,punto_reorden DECIMAL(14,3) NOT NULL,mensaje VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,resuelta_at DATETIME NULL,FOREIGN KEY(material_id) REFERENCES materiales(id),FOREIGN KEY(ubicacion_id) REFERENCES ubicaciones(id),INDEX idx_alerta_estado(estado,material_id,ubicacion_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS facturas(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(80) NOT NULL UNIQUE,orden_id BIGINT UNSIGNED NOT NULL,fecha DATE NOT NULL,monto_crc DECIMAL(14,2) NOT NULL,estado VARCHAR(30) NOT NULL DEFAULT 'REGISTRADA',FOREIGN KEY(orden_id) REFERENCES ordenes_compra(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pagos_registrados(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,factura_id BIGINT UNSIGNED NOT NULL,fecha DATE NOT NULL,monto_crc DECIMAL(14,2) NOT NULL,referencia VARCHAR(120) NULL,FOREIGN KEY(factura_id) REFERENCES facturas(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reglas_negocio(clave VARCHAR(80) PRIMARY KEY,valor_json JSON NOT NULL,actualizado_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS auditoria_eventos(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT UNSIGNED NULL,accion VARCHAR(80) NOT NULL,entidad VARCHAR(80) NOT NULL,entidad_id VARCHAR(80) NULL,detalle_json JSON NULL,request_id VARCHAR(80) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id),INDEX idx_audit_fecha(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_consultas(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT UNSIGNED NOT NULL,pregunta VARCHAR(2000) NOT NULL,referencias_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS requisicion_aprobaciones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,requisicion_id BIGINT UNSIGNED NOT NULL,usuario_id BIGINT UNSIGNED NOT NULL,decision ENUM('APROBADA','RECHAZADA') NOT NULL,comentario VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(requisicion_id) REFERENCES requisiciones(id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cotizaciones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(48) NOT NULL UNIQUE,requisicion_id BIGINT UNSIGNED NOT NULL,proveedor_id BIGINT UNSIGNED NOT NULL,fecha DATE NOT NULL,documento VARCHAR(160) NULL,condiciones VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(requisicion_id) REFERENCES requisiciones(id),FOREIGN KEY(proveedor_id) REFERENCES proveedores(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cotizacion_detalle(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cotizacion_id BIGINT UNSIGNED NOT NULL,material_id BIGINT UNSIGNED NOT NULL,cantidad DECIMAL(14,3) NOT NULL CHECK(cantidad>0),precio_unitario_crc DECIMAL(14,2) NOT NULL CHECK(precio_unitario_crc>=0),FOREIGN KEY(cotizacion_id) REFERENCES cotizaciones(id),FOREIGN KEY(material_id) REFERENCES materiales(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS criterios_evaluacion(id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(48) NOT NULL UNIQUE,nombre VARCHAR(90) NOT NULL,peso DECIMAL(5,2) NOT NULL CHECK(peso>=0 AND peso<=100),activo BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS evaluaciones_proveedor(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,proveedor_id BIGINT UNSIGNED NOT NULL,usuario_id BIGINT UNSIGNED NOT NULL,fecha DATE NOT NULL,comentario VARCHAR(500) NULL,puntaje_ponderado DECIMAL(5,2) NOT NULL,FOREIGN KEY(proveedor_id) REFERENCES proveedores(id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),INDEX idx_eval_proveedor_fecha(proveedor_id,fecha)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS evaluacion_detalle(evaluacion_id BIGINT UNSIGNED NOT NULL,criterio_id SMALLINT UNSIGNED NOT NULL,puntaje TINYINT UNSIGNED NOT NULL CHECK(puntaje BETWEEN 1 AND 5),PRIMARY KEY(evaluacion_id,criterio_id),FOREIGN KEY(evaluacion_id) REFERENCES evaluaciones_proveedor(id),FOREIGN KEY(criterio_id) REFERENCES criterios_evaluacion(id)) ENGINE=InnoDB;
